    "description": "两名知情人士透露，由日本政府支持的基金“产业革新投资机构”（JIC）计划将半导体材料制造商JSR出售给三井化学，交易金额可能超过1.3万亿日元（约合82亿美元）。其中一位知情人士称，最快可能在本月内做出决定。由于相关信息尚未公开，这两位知情人士均拒绝透露姓名。这笔交易可能是日本化工行业最大的交易之一，其规模超过了2020年昭和电工收购日立化成（该交易促成了Resonac Holdings的成立）。（新浪财经）",
    "content": "两名知情人士透露，由日本政府支持的基金“产业革新投资机构”（JIC）计划将半导体材料制造商JSR出售给三井化学，交易金额可能超过1.3万亿日元（约合82亿美元）。其中一位知情人士称，最快可能在本月内做出决定。由于相关信息尚未公开，这两位知情人士均拒绝透露姓名。这笔交易可能是日本化工行业最大的交易之一，其规模超过了2020年昭和电工收购日立化成（该交易促成了Resonac Holdings的成立）。（新浪财经）"
