    "pub_date": "2026-11-04 10:32:03",
    "author": "",
    "description": "党的各级组织是全面从严治党的主体。党的二十届五中全会审议通过的《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》，对持之以恒推进全面从严治党作出系统部署，把“建设上下贯通、执行有力的严密组织体系”列为7项战略任务和重大举措之一。这将有力推进党的组织建设，为坚持和加强党的全面领导、推进党的事业发展提供坚强组织保证。",
