    "content": "11月4日，国务院台办举行例行新闻发布会，有记者问：国际刑警组织第九十四届全体大会将于11月30日至12月3日在香港举行。民进党当局声称台湾地区长期被排除在国际刑警组织之外，全球安全网出现破口，呼吁各国政府支持台湾地区加入该组织，请问对此有何评论？"
