    "content": "新华社北京11月4日电（记者孙奕、孙楠）第七届世界媒体峰会将于11月5日至9日在北京举行。来自全球112个国家和地区的近330家主流媒体、智库、政府部门及联合国和其他国际组织等机构的近500名代表将出席峰会。 峰会秘书处负责人介绍，本届世界媒体峰会主题为“智能变革中的媒体使命与合作行动”，将形成多项成果。峰会期间，将举行开幕式、国际主流媒体合作高端对话会、全体会议、分论坛、科技展、图片展和文化体验活动，中外代表将围绕人工智能普惠发展与全球媒体转型、全球安全挑战中的媒体对话与协作、智能传播拓展文明交流互鉴新空间、“人…"
