    "description": "中新社北京11月4日电 (记者 黄钰钦)11月3日，亚太经合组织(APEC)第37届外交和贸易双部长会议以视频方式在北京举行。会议联合主席中共中央政治局委员、外交部长王毅和商务部长王文涛共同主持。APEC各成员经济体代表、2026年APEC高官会主席、秘书处执行主任、工商咨询理事会主席以及观察员代表参加。",
    "content": "中新社北京11月4日电 (记者 黄钰钦)11月3日，亚太经合组织(APEC)第37届外交和贸易双部长会议以视频方式在北京举行。会议联合主席中共中央政治局委员、外交部长王毅和商务部长王文涛共同主持。APEC各成员经济体代表、2026年APEC高官会主席、秘书处执行主任、工商咨询理事会主席以及观察员代表参加。"
