    "description": "11月2日，达能上海研发与创新中心在上海浦东金桥开发区正式启用。中心总面积约5200平方米，设有一体化研发实验室、900平方米的微生物组研究实验室、300平方米的科学体验与消费者互动空间以及700平方米的中试工厂，专注生命早期营养、成人医学营养、饮用水及饮料等多品类的研究。 记者：张梦洁 杨有宗 新华社音视频部制作 新华社国际传播融合平台出品",
    "content": "11月2日，达能上海研发与创新中心在上海浦东金桥开发区正式启用。中心总面积约5200平方米，设有一体化研发实验室、900平方米的微生物组研究实验室、300平方米的科学体验与消费者互动空间以及700平方米的中试工厂，专注生命早期营养、成人医学营养、饮用水及饮料等多品类的研究。 记者：张梦洁 杨有宗 新华社音视频部制作 新华社国际传播融合平台出品"
