    "title": "央行加力实施股票回购增持再贷款政策",
    "link": "https://m.thepaper.cn/newsDetail_forward_34401706",
    "pub_date": "2026-11-04 09:09:12",
    "author": "",
    "description": "为维护资本市场平稳运行，中国人民银行加力实施股票回购增持再贷款政策。 一、自2026年11月4日起，下调股票回购增持再贷款利率0.25个百分点至1%。股票回购增持再贷款的支持对象为21家全国性银行和5家系统重要性城商行，支持比例为100%，期限1年，可根据银行需要展期。银行可在再贷款利率基础上适当加点，合理确定股票回购增持贷款期限和利率，加快贷款投放，增强上市公司、主要股东市值管理能力。 二、向银行提供充足的再贷款额度保障。11月2日股…",
    "content": "为维护资本市场平稳运行，中国人民银行加力实施股票回购增持再贷款政策。 一、自2026年11月4日起，下调股票回购增持再贷款利率0.25个百分点至1%。股票回购增持再贷款的支持对象为21家全国性银行和5家系统重要性城商行，支持比例为100%，期限1年，可根据银行需要展期。银行可在再贷款利率基础上适当加点，合理确定股票回购增持贷款期限和利率，加快贷款投放，增强上市公司、主要股东市值管理能力。 二、向银行提供充足的再贷款额度保障。11月2日股票回购增持再贷款座谈会之后，银行已向中国人民银行报送股票回购增持再贷款额度申请超…"
