    "content": "知情人士透露，欧洲联盟拟对规模达18万亿欧元（25万亿新元）的单一市场规则作出针对性调整，帮助欧洲企业实现供应链多元化，减少对中国等国家的依赖。 据彭博社引述知情人士报道，欧盟委员会将修改机动车型式认证和外国补贴相关法规，以更有效地应对部分进口产品带来的经济安全风险，同时减少理念相近国家的供应商和企业面对的监管障碍。 欧委会也拟修改强迫劳动相关法规和《商业秘密指令》，便利欧洲企业在欧盟内部市场实现供应链多元化，并提高风险较高的供应商进入这一市场的门槛。 知情人士称，这些调整旨在管理经济安全风险、堵塞监管漏洞，更好地…"
