    "description": "2026年11月04日 令人期待！嫦娥五号和嫦娥六号任务分别从月球正面、月球背面采回的月壤，将在今年中国航展同框亮相，让人们更直观地感受月球。 举头望明月，低头思故乡——这是很多人对月亮的情感寄托，也是我的月亮记忆。儿时仰望月亮，只知月色温柔、诗情隽永。如今研究月球，在实验室中的朝夕相伴，让我读懂：高悬万古的明月，不仅是寄情抒怀的文化符号，更是中华民族求索未知、逐梦星河的精神象征。 早在嫦娥五号月壤样品抵达实验室之前，我们团队就做了充分…",
    "content": "2026年11月04日 令人期待！嫦娥五号和嫦娥六号任务分别从月球正面、月球背面采回的月壤，将在今年中国航展同框亮相，让人们更直观地感受月球。 举头望明月，低头思故乡——这是很多人对月亮的情感寄托，也是我的月亮记忆。儿时仰望月亮，只知月色温柔、诗情隽永。如今研究月球，在实验室中的朝夕相伴，让我读懂：高悬万古的明月，不仅是寄情抒怀的文化符号，更是中华民族求索未知、逐梦星河的精神象征。 早在嫦娥五号月壤样品抵达实验室之前，我们团队就做了充分准备，翻阅海量文献、反复演练实验流程、打磨每一个实验细节。这捧跨越38万公里而来…"
