    "description": "2026年11月04日 将“无障碍环境建设”纳入检察公益诉讼案件范围 本报记者 彭 波 11月2日，检察公益诉讼法草案三次审议稿提请十四届全国人大常委会第二十五次会议审议。草案三审稿进一步完善检察公益诉讼案件范围有关规定，在草案二审稿增加老年人、残疾人等特定群体权益保障的基础上，明确检察院在“无障碍环境建设”领域可以依法提起公益诉讼，同时将“文物等文化遗产保护”修改为“文化遗产保护”。 根据有关建议，草案三审稿完善检察公益诉讼案件管辖有…",
