    "description": "2026年11月04日 新华社北京11月3日电 党的二十届五中全会文件及辅导材料首发式11月3日在北京图书大厦举行。 为帮助广大党员干部群众深入学习领会党的二十届五中全会精神，根据中央有关部门安排，人民出版社、党建读物出版社、学习出版社出版了全会文件及中央有关部门组织编写的权威辅导材料。其中，人民出版社出版了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》单行本、《中国共产党第二十届中央委员会第五次全体会议公报》单行本、《中国…",
