    "content": "2026年11月04日 自2026年11月1日起施行的《市场监督管理所条例》，是首部专门规范市场监督管理所建设和管理的行政法规，标志着基层市场监管体制历经改革整合，正式迈入制度定型新阶段。 当前，我国经营主体数量持续增长，市场交易形态更加多元。“《条例》回应了市场治理需求，对市场监督管理所的职责定位、运行机制、履职规范作出系统规定。”国务院反垄断反不正当竞争委员会专家咨询组成员、中国人民大学法学院院长杨东说。 《条例》以行政法规形式明确市场监督管理所的职责定位和履职要求，既有助于防止监管缺位，也可避免向基层不当转移…"
