    "content": "2026年11月04日 烈士纪念设施是缅怀纪念英烈、弘扬英烈精神的重要载体。退役军人事务部令第12号公布新修订的《烈士纪念设施保护管理办法》，自2026年11月1日起施行。 《办法》在明确国家级、省级、设区的市级、县级保护体系基础上，对未确定保护级别烈士纪念设施提出管护要求，规定了国家级烈士纪念设施申报条件，规范了保护级别申报程序、申报材料、备案程序和保护标志设立有关内容。对于零散烈士墓应当集中迁移保护，确不具备集中保护条件的，应当明确保护力量和管理责任。 “《办法》进一步凸显烈士纪念设施公益属性，细化改陈布展、祭…"
