    "content": "2026年11月04日 近期，农业农村部公布《农村集体经济组织登记办法（试行）》，自2026年11月1日起实施。 农业农村部法规司有关负责人介绍，去年5月《中华人民共和国农村集体经济组织法》施行，登记办法作为重要配套制度，明确了农村集体经济组织设立和变更登记、章程载明事项、名称规范、领证流程、合并分立程序等内容，推动农村集体经济组织规范运行。 登记办法要求，申请登记时，应当提交申请表和相应证明材料；合并、分立或信息发生变更的，以及因合并、分立等原因需要办理注销登记的，应向原登记机关申请并提交有关材料。注销后集体财产…"
