    "description": "2026年11月04日 本报北京11月3日电 （记者吴储岐）记者从民政部近日举行的新闻发布会上获悉：截至9月底，向中度以上失能老年人发放养老服务消费补贴项目累计核销金额93.3亿元，带动养老服务消费404.7亿元，243万失能老年人从中受益。 民政部将继续组织实施该项目，健全失能失智老年人照护体系、优化老年助餐服务等政策措施。指导各地建立健全开办养老机构和老年人福利补贴申领“高效办成一件事”工作机制，进一步推进养老服务师职业资格制度建设…",
