    "content": "2026年11月04日 六盘山西麓，关山脚下，连片的丹参茎叶染上褐红。在甘肃省平凉市庄浪县岳堡镇岔口村，“庄浪丹参·南开一号”田里长势喜人，块根膨大饱满，即将收获。 “杂草长势快，除草要趁早”，庄浪县副县长、南开大学人事处副处长张更辉蹲在垄旁与农户交流。张更辉2025年来到庄浪，负责定点帮扶工作，每周来种植基地协调调度。由于之前多次到庄浪考察，他很清楚当地丹参产业的发展历程。在他之前，南开大学已经派出过4任挂职副县长、近10名驻村第一书记在庄浪探索、积累特色产业发展经验。 2012年，中央确定南开大学对口帮扶庄浪县…"
